/**
 * Tutorial narration: every step is read out loud by a recorded American male voice
 * (public/voice/<step>.<hash>.mp3, generated by `npm run voice` from the step text with the
 * Kokoro neural voice, so it sounds the same in every browser). A clip is only used while its
 * hash matches the current step text; if the text was edited and the clips were not
 * regenerated, that step is simply silent rather than reading out of date words. The player
 * can turn the voice on or off (it starts off; the first tutorial step asks); the choice is remembered.
 */
const KEY = 'benchtech.tutVoice';

/** Turn the card's HTML into plain text for narration (also what the voice clips are generated from). */
export function speakable(html: string): string {
  const div = document.createElement('div');
  div.innerHTML = html;
  // Keep list items and paragraphs as separate sentences
  div.querySelectorAll('li, p, h3').forEach((e) => e.append('. '));
  return (div.textContent ?? '')
    .replace(/[✓✔]/g, '')
    .replace(/[✗✘]/g, 'Uh oh. ')
    .replace(/⚠/g, 'Warning: ')
    .replace(/[▶►]/g, '')
    .replace(/[\u{1F000}-\u{1FAFF}\u2190-\u21FF\u2300-\u23FF\u2600-\u27BF\uFE0F]/gu, '')
    .replace(/\bOL\b/g, 'O L')
    .replace(/•\)+/g, '')
    .replace(/°C/g, ' degrees')
    .replace(/(\d)\s*[–-]\s*(\d)/g, '$1 to $2')
    .replace(/%/g, ' percent')
    .replace(/\bTP(\d)/g, 'test point $1')
    .replace(/\bSW(\d)/g, 'switch $1')
    .replace(/\bF1\b/g, 'F 1')
    .replace(/\bIPA\b/g, 'I P A')
    .replace(/\bPCB\b/g, 'P C B')
    .replace(/\bGND\b/g, 'ground')
    .replace(/\bVBUS\b/g, 'V bus')
    .replace(/Ω/g, ' ohms')
    .replace(/[•·→—]/g, ',')
    .replace(/\?\s*Help/g, 'the Help button')
    .replace(/([!?])\s*\./g, '$1')
    .replace(/\bRobin T\./g, 'Robin T')
    .replace(/\(([^)]*)\)/g, ', $1,')
    .replace(/,\s*,/g, ',')
    .replace(/,\s*\./g, '.')
    .replace(/\s*\.\s*(\.\s*)+/g, '. ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Short stable hash of the narration text (FNV-1a, hex): names the clip file and detects stale clips. */
export function textHash(text: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

export class Narrator {
  private on: boolean;
  private audio = new Audio();
  private token = 0;
  speaking = false;

  constructor() {
    this.on = (() => {
      try {
        // Off until the player asks for it (the welcome step offers it)
        return localStorage.getItem(KEY) === 'on';
      } catch {
        return false;
      }
    })();
    this.audio.preload = 'auto';
  }

  get supported(): boolean {
    return true;
  }

  get enabled(): boolean {
    return this.on;
  }

  setEnabled(v: boolean): void {
    this.on = v;
    try {
      localStorage.setItem(KEY, v ? 'on' : 'off');
    } catch {
      /* ignore */
    }
    if (!v) this.stop();
  }

  private set(v: boolean): void {
    if (this.speaking === v) return;
    this.speaking = v;
    window.dispatchEvent(new CustomEvent('benchtech:speaking', { detail: v }));
  }

  private base(): string {
    return (import.meta.env?.BASE_URL as string | undefined) ?? '/';
  }

  /** Play the recorded clip for this step; resolves true when it was heard to the end. */
  async speak(id: string, text: string): Promise<boolean> {
    this.stop();
    if (!this.on || !text) return false;
    const mine = ++this.token;
    this.audio.src = `${this.base()}voice/${id}.${textHash(text)}.mp3`;
    try {
      await this.audio.play();
    } catch (e) {
      // Blocked until the first click (the replay button then works), or no clip for this text
      if (mine === this.token) this.set(false);
      console.info('[voice]', id, (e as DOMException)?.name);
      return false;
    }
    if (mine !== this.token) return false;
    this.set(true);
    return new Promise<boolean>((resolve) => {
      const done = (ok: boolean) => {
        this.audio.removeEventListener('ended', onEnd);
        this.audio.removeEventListener('error', onErr);
        this.audio.removeEventListener('pause', onPause);
        if (mine === this.token) this.set(false);
        resolve(ok && mine === this.token);
      };
      const onEnd = () => done(true);
      const onErr = () => done(false);
      const onPause = () => !this.audio.ended && done(false);
      this.audio.addEventListener('ended', onEnd);
      this.audio.addEventListener('error', onErr);
      this.audio.addEventListener('pause', onPause);
    });
  }

  stop(): void {
    this.token++;
    this.audio.pause();
    this.set(false);
  }
}
